`default_nettype none
// sync_fifo: first-word fall-through synchronous FIFO (RTL agent, attempt 1)
// Generated by AI agent

module sync_fifo #(
    parameter WIDTH = 8,   //! data width
    parameter DEPTH = 4,   //! entries
    parameter AW    = 2    //! address width, clog2(DEPTH)
) (
    input  wire             clk,      //! clock
    input  wire             rst_n,    //! synchronous reset, active-low
    input  wire             wr_en,    //! write request (pulse per word)
    input  wire [WIDTH-1:0] wr_data,  //! write data
    input  wire             rd_en,    //! read request (pulse per word)
    output wire [WIDTH-1:0] rd_data,  //! oldest word (comb, valid when !empty)
    output wire             full,     //! count == DEPTH (comb from count_ff)
    output wire             empty,    //! count == 0 (comb from count_ff)
    output wire [AW:0]      count     //! stored words (reg)
);

    //==========================================================================
    // storage and pointers
    //==========================================================================
    reg  [WIDTH-1:0] mem [0:DEPTH-1];
    reg  [AW-1:0]    wr_ptr_ff;
    reg  [AW-1:0]    rd_ptr_ff;
    reg  [AW:0]      count_ff;

    wire do_wr = wr_en;
    wire do_rd = rd_en && !empty;

    always @(posedge clk)
        if (do_wr) mem[wr_ptr_ff] <= wr_data;

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_ff <= {AW{1'b0}};
            rd_ptr_ff <= {AW{1'b0}};
        end else begin
            if (do_wr) wr_ptr_ff <= wr_ptr_ff + 1'b1;
            if (do_rd) rd_ptr_ff <= rd_ptr_ff + 1'b1;
        end
    end

    // occupancy (P11): simultaneous write and read nets to zero
    always @(posedge clk) begin
        if (!rst_n) begin
            count_ff <= {(AW+1){1'b0}};
        end else begin
            case ({do_wr, do_rd})
                2'b10   : count_ff <= count_ff + 1'b1;
                2'b01   : count_ff <= count_ff - 1'b1;
                default : count_ff <= count_ff;
            endcase
        end
    end

    assign rd_data = mem[rd_ptr_ff];
    assign count   = count_ff;
    assign full    = (count_ff == DEPTH[AW:0]);
    assign empty   = (count_ff == {(AW+1){1'b0}});

endmodule

`default_nettype wire
